using System.ComponentModel.Composition;

[ExportAttribute(identifierStr(Dynamics.AX.Application.TAMRebateJournalTrans))]
[ExportMetadata(enumStr(ModuleInventCustVend), enumLiteralStr(ModuleInventCustVend, Vend))]
[ExportMetadata(enumStr(TAMRebateSourceType), enumLiteralStr(TAMRebateSourceType, METExternalSalesData))]
internal final class METTAMRebateJournalTransVendExternalData extends TAMRebateJournalTrans
{
    private METRebateScanSupplierTable rebateScanSupplierTable;
    private PurchTable purchTable;

}

Method.Source:
public void setJournalTransaction(Common _journal, Common _transaction)
{
    purchTable = _journal as PurchTable;
    rebateScanSupplierTable = _transaction as METRebateScanSupplierTable;

    //taxGroup = purchLine.TaxGroup; // VNG where to get it from?
    //taxItemGroup = purchLine.TaxItemGroup;
    taxItemGroup = rebateScanSupplierTable.ItemGSTGroup;
    //taxModuleType = purchTable.taxModuleType();
    taxModuleType = TaxModuleType::Purch;

    super(_journal, _transaction);
}

public void inititalizeRebateTransactionFromJournal(TAMRebateTrans _rebateTrans)
{
    super(_rebateTrans);

    /*_rebateTrans.RebateRefAccount = purchTable.InvoiceAccount;
    _rebateTrans.RebateRefId = purchLine.PurchId;
    _rebateTrans.CurrencyCode = purchLine.CurrencyCode;
    _rebateTrans.ItemId = purchLine.ItemId;
    _rebateTrans.RebateRefQty = rebateTable.UnitType == PdsUnitType::CWUnit ? purchLine.PdsCWQty : purchLine.PurchQty;
    _rebateTrans.DefaultDimension = purchLine.DefaultDimension;
    _rebateTrans.CashDiscCode = purchTable.CashDisc;
    _rebateTrans.RefUnitId = rebateTable.UnitType == PdsUnitType::CWUnit ? purchLine.pdsCWUnitId() : purchLine.PurchUnit;
    _rebateTrans.InventDimId = purchLine.InventDimId;

    _rebateTrans.RebateRefSoldToAccount = purchTable.InvoiceAccount;*/

    // VNG hope we are not doing catch weight here

    _rebateTrans.RebateRefAccount = rebateScanSupplierTable.VendAccount;
    _rebateTrans.RebateRefId = rebateScanSupplierTable.TransactionNumber;
    _rebateTrans.CurrencyCode = rebateScanSupplierTable.CurrencyCode;
    _rebateTrans.ItemId = rebateScanSupplierTable.ItemId;
    _rebateTrans.RebateRefQty = rebateScanSupplierTable.SalesQty;
    //_rebateTrans.DefaultDimension = purchLine.DefaultDimension;
    _rebateTrans.CashDiscCode = "";
    _rebateTrans.RefUnitId = rebateScanSupplierTable.UnitOfMeasure;
    _rebateTrans.InventDimId = InventDim::findOrCreateBlank().inventDimId;

    _rebateTrans.RebateRefSoldToAccount = rebateScanSupplierTable.VendAccount;

    _rebateTrans.METExternalSalesDataTable = rebateScanSupplierTable.RecId;
}

protected TAMRebateRefAmount calcJournalTransAmountExclTax()
{
    //return purchLine.calcLineAmountExclTax();
    return rebateScanSupplierTable.SalesValue;
}

protected TAMRebateRefAmount calcJournalTransGrossAmountExclTax()
{
    //return purchLine.calcGrossAmountExclTax();
    return rebateScanSupplierTable.SalesValue; // same as above?
}
